import {componentDefinition} from './core.js';
import {pinPoint,componentBounds} from './geometry.js';
export function labelWire(project,id){const w=project.wires.find(w=>w.id===id);if(!w)throw Error('Kablo bulunamadı.');if(project.components.length>148||project.wires.length>599)throw Error('Etiketler için bileşen / kablo sınırı dolu.');const taken=new Set(project.components.filter(c=>c.type==='netLabel').map(c=>c.params.name));let n=1;while(taken.has('NET'+n))n++;const name='NET'+n,ids=new Set(project.components.map(c=>c.id));let k=1;const next=()=>{while(ids.has('label'+k))k++;const id='label'+k++;ids.add(id);return id;};const added=[],labels=[];
 for(const ep of [w.from,w.to]){const point=pinPoint(project,ep),c=project.components.find(c=>c.id===ep.split(':')[0]),b=componentBounds(c),distances=[['left',point.x-c.x],['right',c.x+b.width-point.x],['top',point.y-c.y],['bottom',c.y+b.height-point.y]],side=c.type==='led'?(ep.endsWith(':A')?'left':'right'):distances.sort((a,b)=>a[1]-b[1])[0][0],label={id:next(),type:'netLabel',x:c.x+b.width+40,y:point.y-16,rotation:0,params:{name,side:'left'}};if(side==='left'){label.x=c.x-190;label.params.side='right';}if(side==='top'){label.x=point.x-75;label.y=c.y-72;label.params.side='bottom';}if(side==='bottom'){label.x=point.x-75;label.y=c.y+b.height+40;label.params.side='top';}if(Math.abs(label.x)>10000||Math.abs(label.y)>10000)throw Error('Etiket çalışma alanı sınırının dışında. Bileşeni içeri taşıyın.');labels.push(label);added.push({from:ep,to:label.id+':NET'});}

 project.components.push(...labels);project.wires=project.wires.filter(v=>v.id!==id);const wireIds=new Set(project.wires.map(v=>v.id));for(const a of added){let i=1;while(wireIds.has('labelwire'+i))i++;wireIds.add('labelwire'+i);project.wires.push({id:'labelwire'+i,...a,color:w.color,points:[]});}return name;
}
